import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"子夏易傳 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"子夏易傳 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"classics/zixia/054.md","filePath":"classics/zixia/054.md"}'),i={name:"classics/zixia/054.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><p>卦辭：艮，其背不獲其身，行其庭不見其人，無咎。</p><p>彖曰：艮，止也。時止則止，時行則行。動靜不失其時，其道光明。艮其止，止其所也。上下敵，應不相與也。是以不獲其身，行其庭不見其人，無咎也。</p><p>子夏：艮兩止也。各止於所，嚮也。見敵應而咎生也。不獲其身，不欲彼見於我也。至近而不可通，雖行其庭不見其人。我無見於彼也。不相見也。何敵之有乎，故無咎也。君子之道，無固也，時可止則止之，時可動則動之，消息以時，而道乃光也。</p><p>象曰：兼山，艮。君子以思不出其位。</p><p>子夏：一體而兩山，兼山者也。位身之止也，思不出其位，止者也。</p><p>初六，艮其趾，無咎。利永貞。</p><p>象曰：艮其趾，未失正也。</p><p>子夏：止於下，艮於趾也。艮則不行也。得其止未失其正也，何所咎乎。利於長正，得其久也。</p><p>六二，艮其腓，不拯其隨，其心不快。</p><p>象曰：不拯其隨，未退聽也。</p><p>子夏：腓隨足也，自動則躁妄也，何益於動乎。艮體不動，則腓不得舉而隨也，性躁而不得往，未退而聽命，故其心不快也。</p><p>九三，艮其限，列其夤，厲薫心。</p><p>象曰：艮其限，危薫心也。</p><p>子夏：艮於下體而不得通於上，止於體之中也。分其體，夤列矣。危及至心也。知其不可，而不可相見，則全其體。至於三，限其止乃止也。而敵之乃處中道而止之，於事則中分矣，羞辱至故，危薫哉。</p><p>六四，艮其身，無咎。</p><p>象曰：艮其身，止諸躬也。</p><p>子夏：上體兼下，兼兩而止，則時止能止，其身當位，而靜止得於分，故無咎也。</p><p>六五，艮其輔，言有序，悔亡。</p><p>象曰：艮其輔，以中正也。</p><p>子夏：上體之中，當其輔也。得其中正言也。言而序，悔亡者也。</p><p>上九，敦艮吉。</p><p>象曰：敦艮之吉，以厚終也。</p><p>子夏：動者，利之求也。動失則害至。止者，正之元也，久守則福來，非敦厚之徳不能止其終也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
